include  <p>class EnergySphere { public:     struct AnimationParams {         float animationTime = 0.0f;         float pulseSpeed = 1.0f;         float pulseIntensity = 1.0f;         float colorHue = 0.66f;        // Blue by default         float colorSaturation = 1.0f;         float glowStrength = 3.0f;         float jiggleAmount = 0.0f;     };</p> <pre><code>AnimationParams params;

bool Load(const std::string&amp; filepath) {
    Assimp::Importer importer;
    const aiScene* scene = importer.ReadFile(filepath,
        aiProcess_Triangulate |
        aiProcess_GenNormals |
        aiProcess_CalcTangentSpace
    );

    if (!scene || scene-&gt;mFlags &amp; AI_SCENE_FLAGS_INCOMPLETE || !scene-&gt;mRootNode) {
        std::cerr &lt;&lt; "Assimp Error: " &lt;&lt; importer.GetErrorString() &lt;&lt; std::endl;
        return false;
    }

    LoadCustomProperties(scene);
    ProcessNode(scene-&gt;mRootNode, scene);

    return true;
}
